// kleine helper voor {placeholders}
function fill(tpl, vars) {
  return String(tpl).replace(/\{(\w+)\}/g, (m, k) => (vars && vars[k] !== undefined ? vars[k] : m));
}

module.exports = { pl, en, nl, fill };
